import React, { useState, useMemo } from 'react';
import PostItem from './PostItem';
import './PostList.css';

const PostList = ({ posts, loading, onEdit, onDelete }) => {
  const [searchQuery, setSearchQuery] = useState('');
  const [sortBy, setSortBy] = useState('newest');

  const filteredAndSortedPosts = useMemo(() => {
    let result = [...posts];

    if (searchQuery.trim()) {
      const q = searchQuery.toLowerCase();
      result = result.filter(
        post =>
          post.title?.toLowerCase().includes(q) ||
          post.author?.toLowerCase().includes(q) ||
          post.content?.toLowerCase().includes(q)
      );
    }

    result.sort((a, b) => {
      if (sortBy === 'newest') {
        return new Date(b.publishedDate || 0) - new Date(a.publishedDate || 0);
      }
      if (sortBy === 'oldest') {
        return new Date(a.publishedDate || 0) - new Date(b.publishedDate || 0);
      }
      if (sortBy === 'title') {
        return (a.title || '').localeCompare(b.title || '');
      }
      return 0;
    });

    return result;
  }, [posts, searchQuery, sortBy]);

  if (loading && posts.length === 0) {
    return (
      <section className="post-list-section fade-in" aria-labelledby="posts-heading">
        <div className="loading-container">
          <div className="loading-spinner" aria-hidden="true"></div>
          <p className="loading-text">Gathering the latest stories for you...</p>
        </div>
      </section>
    );
  }

  if (posts.length === 0) {
    return (
      <section className="post-list-section fade-in" aria-labelledby="posts-heading">
        <div className="empty-state">
          <div className="empty-emoji-badge" aria-hidden="true">✨</div>
          <h3 id="posts-heading" className="empty-title">Your feed is awaiting its first spark</h3>
          <p className="empty-description">
            Every inspiring blog begins with a single thought. Use the story builder on the left to publish your first piece!
          </p>
        </div>
      </section>
    );
  }

  return (
    <section className="post-list-section fade-in" aria-labelledby="posts-heading">
      <header className="list-header">
        <div className="list-header-title-wrap">
          <h2 id="posts-heading" className="list-title">📚 Published Stories</h2>
          <span className="post-count">
            {posts.length} {posts.length === 1 ? 'story' : 'stories'}
          </span>
        </div>

        <div className="list-controls">
          <div className="search-input-wrap">
            <svg className="search-icon" width="16" height="16" fill="none" stroke="currentColor" viewBox="0 0 24 24" aria-hidden="true">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
            </svg>
            <input
              type="text"
              placeholder="Search stories, topics, or authors..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="search-input"
              aria-label="Search stories"
            />
            {searchQuery && (
              <button 
                type="button" 
                className="search-clear" 
                onClick={() => setSearchQuery('')}
                aria-label="Clear search"
              >
                ×
              </button>
            )}
          </div>

          <div className="sort-select-wrap">
            <select
              value={sortBy}
              onChange={(e) => setSortBy(e.target.value)}
              className="sort-select"
              aria-label="Sort stories by"
            >
              <option value="newest">🕒 Latest First</option>
              <option value="oldest">🕰️ Oldest First</option>
              <option value="title">🔤 Alphabetical (A-Z)</option>
            </select>
          </div>
        </div>
      </header>

      {filteredAndSortedPosts.length === 0 ? (
        <div className="empty-search-state">
          <span className="empty-search-icon">🔍</span>
          <h4>No stories found</h4>
          <p>We couldn't find any stories matching <strong>"{searchQuery}"</strong>.</p>
          <button 
            type="button" 
            className="btn btn-secondary btn-sm" 
            onClick={() => setSearchQuery('')}
          >
            Clear Search
          </button>
        </div>
      ) : (
        <div className="posts-grid" role="list">
          {filteredAndSortedPosts.map(post => (
            <PostItem
              key={post._id}
              post={post}
              onEdit={onEdit}
              onDelete={onDelete}
            />
          ))}
        </div>
      )}
    </section>
  );
};

export default PostList;
